PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS plans (id TEXT PRIMARY KEY, name TEXT NOT NULL, monthly INTEGER NOT NULL, yearly INTEGER NOT NULL, shops INTEGER NOT NULL, products INTEGER NOT NULL, branding INTEGER NOT NULL CHECK(branding IN(0,1)));
INSERT OR IGNORE INTO plans VALUES ('free','Free',0,0,1,10,1),('starter','Starter',19900,199000,1,30,0),('growth','Growth',49900,499000,1,100,0),('brand','Brand',99000,990000,3,500,0);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password TEXT NOT NULL,plan_id TEXT NOT NULL DEFAULT 'free' REFERENCES plans(id));
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_sessions_expiry ON sessions(expires);
CREATE TABLE IF NOT EXISTS login_attempts(key TEXT PRIMARY KEY,count INTEGER NOT NULL,reset_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS shops(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),slug TEXT NOT NULL UNIQUE,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',line_url TEXT NOT NULL DEFAULT '',published INTEGER NOT NULL DEFAULT 0 CHECK(published IN(0,1)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_shops_owner ON shops(owner_id);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,shop_id TEXT NOT NULL REFERENCES shops(id) ON DELETE CASCADE,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',price INTEGER CHECK(price>=0),source_url TEXT NOT NULL,image_key TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_products_shop_status ON products(shop_id,status);
CREATE TABLE IF NOT EXISTS media(key TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),mime TEXT NOT NULL,size INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_media_owner ON media(owner_id);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,shop_id TEXT NOT NULL REFERENCES shops(id) ON DELETE CASCADE,product_id TEXT,kind TEXT NOT NULL CHECK(kind IN('view','buy_click')),day TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_events_shop_day ON events(shop_id,day,kind);
